using System.Text.Json.Nodes;
using System.Text.RegularExpressions;
using MPCore.Transport.Grpc.Tests.Contracts;

namespace MPCore.Transport.Grpc.Tests;

/// <summary>
/// The 1.0 contracts of the command line tool and of the template (docs/contracts). Each is generated by running
/// the built tool and the template from this checkout, not written by hand, so that what a consumer depends on is
/// read from the code that serves it.
/// </summary>
public sealed partial class GeneratedBackendTests
{
    private const string RegenerateCli = "MPCORE_UPDATE_CONTRACTS=1 dotnet test tests/MPCore.Transport.Grpc.Tests --filter \"FullyQualifiedName~The_checked_in_cli_contract\"";
    private const string RegenerateTemplate = "MPCORE_UPDATE_CONTRACTS=1 dotnet test tests/MPCore.Transport.Grpc.Tests --filter \"FullyQualifiedName~The_checked_in_template_contract\"";

    [Fact]
    public async Task The_checked_in_cli_contract_is_what_the_tool_declares()
    {
        using var workspace = await Workspace.WithTemplateAsync();

        var contract = await CliContract.BuildAsync(workspace);

        ContractFacts.AssertFileIs("cli.json", contract, RegenerateCli);
    }

    [Fact]
    public async Task The_checked_in_template_contract_is_what_the_template_declares_and_generates()
    {
        using var workspace = await Workspace.WithTemplateAsync();

        var contract = await TemplateContract.BuildAsync(workspace);

        ContractFacts.AssertFileIs("template.json", contract, RegenerateTemplate);
    }

    /// <summary>What the command line tool prints and returns, found by running it.</summary>
    private static class CliContract
    {
        public static async Task<JsonNode> BuildAsync(Workspace workspace)
        {
            var cli = Workspace.CliAssembly();
            var scratch = Directory.CreateDirectory(Path.Combine(workspace.Root, "probes")).FullName;
            var probes = new SortedDictionary<string, int>(StringComparer.Ordinal);

            async Task<(int ExitCode, string Output)> RunAsync(string label, string directory, params string[] arguments)
            {
                var result = await workspace.RunDotnetAsync(directory, [cli, .. arguments]);
                probes[label] = result.ExitCode;
                return result;
            }

            // The usage the tool prints when it is not given a command it knows.
            var usage = await RunAsync("no arguments", scratch);
            var newBackend = ParseNewBackendUsage(usage.Output);
            var configure = ParseConfigureUsage(usage.Output);

            // The values each option accepts, as the validation itself says them.
            var valid = new[] { "new", "backend", "--organization", "Acme", "--component", "Catalog", "--output", Path.Combine(scratch, "not-created"), "--transport", "rest", "--non-interactive" };
            foreach (var option in new[] { "shape", "messaging", "cache", "timeseries", "business-audit", "transport", "ai-tooling" })
            {
                var (_, output) = await RunAsync($"new backend: a value --{option} does not accept", scratch, [.. Override(valid, option, "no-such-value")]);
                newBackend[option] = newBackend[option] with { Choices = AgreeingChoices("new backend", option, newBackend[option], output) };
            }

            // The presets and the values each sets.
            var presets = await RunAsync("new backend: list the presets", scratch, "new", "backend", "--list-presets");
            var presetValues = ParsePresets(presets.Output);
            Assert.Equal(
                [.. newBackend["preset"].Choices!.Order(StringComparer.Ordinal)],
                [.. presetValues.Keys.Order(StringComparer.Ordinal)]);
            await RunAsync("new backend: a preset that does not exist", scratch, "new", "backend", "--preset", "no-such-preset", "--non-interactive");
            await RunAsync("new backend: a required option is missing", scratch, "new", "backend", "--non-interactive");
            await RunAsync("new backend: a name that is not PascalCase", scratch, [.. Override(valid, "organization", "acme")]);
            await RunAsync("new backend: a version range for MP Core", scratch, [.. valid, "--mpcore-version", "1.*"]);
            await RunAsync("new backend: an authority that looks like a credential", scratch, [.. valid, "--security-authority", "password-in-the-url"]);

            var occupied = Directory.CreateDirectory(Path.Combine(scratch, "occupied")).FullName;
            File.WriteAllText(Path.Combine(occupied, "file.txt"), "x");
            await RunAsync("new backend: the output directory is not empty", scratch, [.. Override(valid, "output", occupied)]);

            // A repository generated with only the required options: what is left unsaid is the default.
            var repository = Path.Combine(scratch, "repository");
            var generated = await RunAsync(
                "new backend: a repository is generated", scratch,
                "new", "backend", "--organization", "Acme", "--component", "Catalog", "--output", repository, "--transport", "rest", "--skip-verify", "--non-interactive");
            Assert.True(generated.ExitCode == 0, generated.Output);
            var manifest = JsonNode.Parse(File.ReadAllText(Path.Combine(repository, ".mpcore/template-manifest.json")))!.AsObject();
            foreach (var (option, member) in new[]
                     {
                         ("shape", "shape"), ("messaging", "messaging"), ("business-audit", "businessAudit"), ("cache", "cache"),
                         ("timeseries", "timeseries"), ("ai-tooling", "aiTooling"), ("mpcore-version", "mpcoreVersion"),
                     })
            {
                var value = manifest[member]!.GetValue<string>();
                newBackend[option] = newBackend[option] with { Default = value == CohortVersion() ? "<cohort version>" : value };
            }

            // The tool that changes a generated repository.
            foreach (var option in new[] { "cache", "business-audit", "timeseries", "ai-tooling" })
            {
                var (_, output) = await RunAsync($"configure: a value --{option} does not accept", scratch, "configure", "--project", repository, $"--{option}", "no-such-value");
                configure[option] = configure[option] with { Choices = AgreeingChoices("configure", option, configure[option], output) };
            }

            await RunAsync("configure: --project is missing", scratch, "configure");
            await RunAsync("configure: the directory is not a repository of MP Core", scratch, "configure", "--project", scratch);
            await RunAsync("configure: the plan changes nothing", scratch, "configure", "--project", repository);
            await RunAsync("configure: the plan switches the cache", scratch, "configure", "--project", repository, "--cache", "redis");
            await RunAsync("configure: the transport cannot be changed", scratch, "configure", "--project", repository, "--transport", "grpc");
            var unsupported = Directory.CreateDirectory(Path.Combine(scratch, "unsupported", ".mpcore")).Parent!.FullName;
            File.WriteAllText(Path.Combine(unsupported, ".mpcore/template-manifest.json"), "{ \"schemaVersion\": 3 }");
            await RunAsync("configure: the manifest has another schema version", scratch, "configure", "--project", unsupported);

            var members = new SortedDictionary<string, string>(StringComparer.Ordinal);
            foreach (var (name, value) in manifest)
            {
                members[name] = value is JsonValue json && json.TryGetValue<string>(out _) ? "string" : "number";
            }

            var contract = new JsonObject
            {
                ["tool"] = "mpcore",
                ["commands"] = new JsonObject
                {
                    ["configure"] = new JsonObject { ["options"] = Describe(configure) },
                    ["new backend"] = new JsonObject { ["options"] = Describe(newBackend) },
                },
                ["manifest"] = new JsonObject
                {
                    ["path"] = ".mpcore/template-manifest.json",
                    ["schemaVersion"] = manifest["schemaVersion"]!.GetValue<int>(),
                    ["members"] = new JsonObject([.. members.Select(static member => KeyValuePair.Create<string, JsonNode?>(member.Key, member.Value))]),
                },
                ["presets"] = new JsonObject([.. presetValues.Select(static preset => KeyValuePair.Create<string, JsonNode?>(
                    preset.Key,
                    new JsonObject([.. preset.Value.Select(static pair => KeyValuePair.Create<string, JsonNode?>(pair.Key, pair.Value))])))]),
                ["probes"] = new JsonObject([.. probes.Select(static probe => KeyValuePair.Create<string, JsonNode?>(
                    probe.Key,
                    new JsonObject { ["exitCode"] = probe.Value }))]),
            };
            return contract;
        }

        private sealed record Option(bool Required, string Kind, IReadOnlyList<string>? Choices = null, string? Default = null);

        private static string CohortVersion() =>
            Regex.Match(File.ReadAllText(Path.Combine(ContractFacts.RepositoryRoot, "src/Directory.Build.props")), "<VersionPrefix>([^<]+)</VersionPrefix>").Groups[1].Value;

        private static string[] Override(string[] arguments, string option, string value)
        {
            var copy = arguments.ToArray();
            var at = Array.IndexOf(copy, $"--{option}");
            if (at < 0)
            {
                return [.. copy, $"--{option}", value];
            }

            copy[at + 1] = value;
            return copy;
        }

        /// <summary>
        /// The values of an option as the usage names them and as the validation says them must be the same set:
        /// a refusal that lists other values than the usage does is a defect, found here before a consumer finds it.
        /// </summary>
        private static IReadOnlyList<string> AgreeingChoices(string command, string option, Option usage, string output)
        {
            var message = Regex.Match(output, $@"^--{Regex.Escape(option)} must be (?<list>.+)\.\s*$", RegexOptions.Multiline);
            Assert.True(message.Success, $"{command} --{option}: no refusal naming the accepted values in:\n{output}");
            var said = message.Groups["list"].Value.Replace(", or ", ", ").Replace(" or ", ", ").Split(", ").Order(StringComparer.Ordinal).ToList();
            Assert.Equal("choice", usage.Kind);
            Assert.True(
                said.SequenceEqual(usage.Choices!.Order(StringComparer.Ordinal), StringComparer.Ordinal),
                $"{command} --{option}: the usage lists {string.Join('|', usage.Choices!)} and the validation accepts {string.Join('|', said)}.");
            return said;
        }

        private static Dictionary<string, Option> ParseNewBackendUsage(string output)
        {
            var line = output.Split('\n').Single(static text => text.StartsWith("mpcore new backend ", StringComparison.Ordinal));
            var tokens = line["mpcore new backend ".Length..].Replace("[", " [ ").Replace("]", " ] ").Split(' ', StringSplitOptions.RemoveEmptyEntries);
            var options = new Dictionary<string, Option>(StringComparer.Ordinal);
            var depth = 0;
            for (var index = 0; index < tokens.Length; index++)
            {
                switch (tokens[index])
                {
                    case "[":
                        depth++;
                        break;
                    case "]":
                        depth--;
                        break;
                    case "|":
                        break;
                    case var token when token.StartsWith("--", StringComparison.Ordinal):
                        var value = index + 1 < tokens.Length && tokens[index + 1] is not ("[" or "]" or "|") && !tokens[index + 1].StartsWith("--", StringComparison.Ordinal)
                            ? tokens[++index]
                            : null;
                        options[token[2..]] = Described(required: depth == 0, value);
                        break;
                }
            }

            Assert.Equal(0, depth);
            return options;
        }

        private static Dictionary<string, Option> ParseConfigureUsage(string output)
        {
            var lines = output.Split('\n');
            var first = Array.FindIndex(lines, static text => text.StartsWith("mpcore configure ", StringComparison.Ordinal));
            Assert.True(first >= 0, "The usage names no configure command.");
            var options = new Dictionary<string, Option>(StringComparer.Ordinal)
            {
                ["project"] = Described(required: true, "<path>"),
                ["apply"] = Described(required: false, null),
            };
            Assert.Contains("--project <path>", lines[first], StringComparison.Ordinal);
            Assert.Contains("[--apply]", lines[first], StringComparison.Ordinal);
            foreach (var text in lines.Skip(first + 1))
            {
                var match = Regex.Match(text, @"^  --(?<name>[a-z-]+) (?<value>\S+)\s{2,}");
                if (match.Success)
                {
                    options[match.Groups["name"].Value] = Described(required: false, match.Groups["value"].Value);
                }
            }

            return options;
        }

        private static Option Described(bool required, string? value) => value switch
        {
            null => new Option(required, "flag"),
            _ when value.Contains('|', StringComparison.Ordinal) => new Option(required, "choice", [.. value.Split('|')]),
            _ => new Option(required, "value"),
        };

        private static SortedDictionary<string, SortedDictionary<string, string>> ParsePresets(string output)
        {
            var presets = new SortedDictionary<string, SortedDictionary<string, string>>(StringComparer.Ordinal);
            foreach (var text in output.Split('\n').Where(static text => text.StartsWith("  ", StringComparison.Ordinal)))
            {
                var parts = text.Trim().Split(' ', StringSplitOptions.RemoveEmptyEntries);
                var values = new SortedDictionary<string, string>(StringComparer.Ordinal);
                for (var index = 1; index + 1 < parts.Length; index += 2)
                {
                    Assert.StartsWith("--", parts[index], StringComparison.Ordinal);
                    values[parts[index][2..]] = parts[index + 1];
                }

                presets[parts[0]] = values;
            }

            Assert.NotEmpty(presets);
            return presets;
        }

        private static JsonObject Describe(Dictionary<string, Option> options) =>
            new([.. options.OrderBy(static pair => pair.Key, StringComparer.Ordinal).Select(static pair =>
            {
                var description = new JsonObject { ["kind"] = pair.Value.Kind, ["required"] = pair.Value.Required };
                if (pair.Value.Choices is not null)
                {
                    description["choices"] = new JsonArray([.. pair.Value.Choices.Order(StringComparer.Ordinal).Select(static choice => (JsonNode?)JsonValue.Create(choice))]);
                }

                if (pair.Value.Default is not null)
                {
                    description["default"] = pair.Value.Default;
                }

                return KeyValuePair.Create<string, JsonNode?>(pair.Key, description);
            })]);
    }

    /// <summary>What the template declares as its parameters, and the files it generates for each shape and transport.</summary>
    private static class TemplateContract
    {
        public static async Task<JsonNode> BuildAsync(Workspace workspace)
        {
            var template = JsonNode.Parse(File.ReadAllText(Path.Combine(TemplateRoot, ".template.config/template.json")))!.AsObject();
            var parameters = new SortedDictionary<string, JsonNode?>(StringComparer.Ordinal);
            foreach (var (name, symbol) in template["symbols"]!.AsObject())
            {
                if (symbol!["type"]?.GetValue<string>() != "parameter")
                {
                    continue;
                }

                var description = new JsonObject
                {
                    ["datatype"] = symbol["datatype"]?.GetValue<string>() ?? "string",
                    ["required"] = symbol["isRequired"]?.GetValue<bool>() ?? false,
                };
                if (symbol["defaultValue"] is { } defaultValue)
                {
                    description["default"] = defaultValue.GetValue<string>() == CohortVersionValue() ? "<cohort version>" : defaultValue.GetValue<string>();
                }

                if (symbol["choices"] is JsonArray choices)
                {
                    description["choices"] = new JsonArray([.. choices.Select(static choice => (JsonNode?)JsonValue.Create(choice!["choice"]!.GetValue<string>())).OrderBy(static choice => choice!.GetValue<string>(), StringComparer.Ordinal)]);
                }

                parameters[name] = description;
            }

            var generated = new SortedDictionary<string, SortedSet<string>>(StringComparer.Ordinal);
            foreach (var shape in new[] { "service", "modular-monolith" })
            {
                foreach (var transport in new[] { "grpc", "rest", "both" })
                {
                    var output = Path.Combine(workspace.Root, $"{shape}-{transport}");
                    var result = await workspace.RunDotnetAsync(
                        workspace.Root,
                        "new", "mpcore-backend", "--name", "Acme.Ledger", "--output", output, "--organization", "Acme", "--component", "Ledger",
                        "--shape", shape, "--transport", transport);
                    Assert.True(result.ExitCode == 0, result.Output);
                    generated[$"{shape}/{transport}"] = [.. Directory.EnumerateFiles(output, "*", SearchOption.AllDirectories)
                        .Select(path => Path.GetRelativePath(output, path).Replace('\\', '/').Replace("Acme.Ledger", "<Product>", StringComparison.Ordinal))];
                }
            }

            var common = generated.Values.Aggregate((left, right) => [.. left.Intersect(right, StringComparer.Ordinal)]);
            var files = new JsonObject { ["common"] = new JsonArray([.. common.Select(static path => (JsonNode?)JsonValue.Create(path))]) };
            var combinations = new JsonObject();
            foreach (var (combination, paths) in generated)
            {
                var extra = paths.Except(common, StringComparer.Ordinal).ToList();
                combinations[combination] = new JsonObject { ["also"] = new JsonArray([.. extra.Select(static path => (JsonNode?)JsonValue.Create(path))]) };
            }

            files["by shape and transport"] = combinations;
            return new JsonObject
            {
                ["template"] = template["shortName"]!.GetValue<string>(),
                ["parameters"] = new JsonObject([.. parameters]),
                ["files"] = files,
            };
        }

        private static string CohortVersionValue() =>
            Regex.Match(File.ReadAllText(Path.Combine(ContractFacts.RepositoryRoot, "src/Directory.Build.props")), "<VersionPrefix>([^<]+)</VersionPrefix>").Groups[1].Value;
    }
}
